import java.util.*; import com.aicommerce.platform.delivery.domain.PlatformReconciliationTerminalCode;
public record ReconciliationTerminalFailure(PlatformReconciliationTerminalCode errorCode,Optional<String> safeProviderTraceId,NormalizedPlatformEvidence evidence) implements PlatformReconciliationOutcome{public ReconciliationTerminalFailure{PlatformContractSupport.req(errorCode);safeProviderTraceId=PlatformContractSupport.opt(safeProviderTraceId);PlatformContractSupport.req(evidence);safeProviderTraceId.ifPresent(PlatformContractSupport::safe);if(evidence.attemptKind()!=com.aicommerce.platform.delivery.domain.PlatformAttemptKind.RECONCILE||evidence.resultKind()!=com.aicommerce.platform.delivery.domain.PlatformEvidenceResultKind.FAILED_TERMINAL)throw PlatformContractSupport.invalid();}}
